package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;

public class RefuseRetiredInput {
    // The date a claim is being added to (a blank date is the sheet's today) must not be after its person's retirement.
    public void refuse(@Val ClaimInput input, @Val Person person, Sheets sheets) throws ClaimAfterRetirementException {
        check(person, input.date() != null ? input.date() : sheets.today(person.sheetId()));
    }

    static void check(Person person, LocalDate date) throws ClaimAfterRetirementException {
        if (person != null && person.retired() && date.isAfter(person.retiredFrom())) {
            throw new ClaimAfterRetirementException(person.name() + " is retired from " + person.retiredFrom()
                    + ": no claim dated " + date + " can be added or edited.");
        }
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

public class RefuseClosedInput {
    // The date a claim is being added or edited to (a blank date is the sheet's today) must not be in a closed period.
    public void refuse(@PathVariable("sheetId") String sheetId, @Val ClaimInput input, Sheets sheets, Periods periods)
            throws ClaimInClosedPeriodException {
        String sheet = sheetId.trim();
        LocalDate date = input.date() != null ? input.date() : sheets.today(sheet);
        Period closed = periods.closedOn(sheet, date);
        if (closed != null) {
            throw new ClaimInClosedPeriodException("The period " + closed.name() + " is closed: no claim dated "
                    + date + " can be added or edited.");
        }
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;

public class AddClaim {
    // The due-by is fixed now: the claim's date plus the terms of its person's grade in force on that date.
    // Its status log starts with its DRAFT line, at its due as shown now.
    public void add(@Val ClaimInput input, @Val Person person, Claims claims, Sheets sheets, Settings settings,
            Rollup rollup, ServerHttpConnection connection, Out<Claim> claimOut) {
        LocalDate date = input.date() != null ? input.date() : sheets.today(person.sheetId());
        LocalDate dueBy = date.plusDays(settings.terms(person.sheetId(), person.gradeOn(date), date));
        Claim claim = claims.add(person.sheetId(), person.id(), input.amount(), date, input.note(), input.corrects(),
                dueBy);
        claims.log(claim, Audit.user(connection).trim(), sheets.today(person.sheetId()), rollup.figure(claim));
        claimOut.set(claim);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;

public class AuditClaimAdded {
    public void audit(@Val Claim claim, @Val Person person,
            ServerHttpConnection connection, Audit audit) {
        ClaimResponse shown = ClaimResponse.from(claim);
        audit.record(Audit.line("CLAIM_ADDED", claim.sheetId(), Audit.user(connection), "person=" + person.name(),
                "amount=" + shown.amount(), "date=" + shown.date()));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithClaim {
    public void respond(@Val Claim claim, ObjectResponse<ClaimResponse> response) {
        response.send(ClaimResponse.from(claim));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadPerson {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("personId") long personId,
            People people, Out<Person> personOut) throws PersonNotFoundException {
        Person person = people.find(sheetId.trim(), personId);
        if (person == null) {
            throw new PersonNotFoundException("No person " + personId + " on this sheet.");
        }
        personOut.set(person);
    }
}

