package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidatePaste {
    // Every line is checked before any is added: name,amount,date,note — the name a person on the sheet (ignoring
    // case and surrounding spaces), the rest by the claim form's rules (a blank date is the sheet's today, the note
    // may hold commas or be absent). Blank lines are skipped; a paste with no line is refused.
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody PasteRequest body, People people,
            Sheets sheets, Periods periods, Out<PastedLines> out)
            throws InvalidClaimException, ClaimInClosedPeriodException, ClaimAfterRetirementException {
        String sheet = sheetId.trim();
        String text = body == null || body.text() == null ? "" : body.text();
        List<PastedLine> lines = new ArrayList<>();
        int n = 0;
        for (String line : text.split("\\r?\\n")) {
            n++;
            if (line.isBlank()) {
                continue;
            }
            String[] fields = line.split(",", 4);
            if (fields.length < 2) {
                throw new InvalidClaimException("Line " + n + ": type name,amount,date,note.");
            }
            String name = fields[0].trim();
            Person person = name.isEmpty() ? null : people.findByName(sheet, name);
            if (person == null) {
                throw new InvalidClaimException("Line " + n + ": no person " + name + " on this sheet.");
            }
            ClaimInput input;
            try {
                input = ValidateClaim.parse(new ClaimRequest(fields[1], fields.length > 2 ? fields[2] : "",
                        fields.length > 3 ? fields[3] : "", ""));
            } catch (InvalidClaimException e) {
                throw new InvalidClaimException("Line " + n + ": " + e.getMessage());
            }
            LocalDate date = input.date() != null ? input.date() : sheets.today(sheet);
            Period closed = periods.closedOn(sheet, date);
            if (closed != null) {
                throw new ClaimInClosedPeriodException("Line " + n + ": the period " + closed.name()
                        + " is closed: no claim dated " + date + " can be added.");
            }
            RefuseRetiredInput.check(person, date);
            lines.add(new PastedLine(person, input));
        }
        if (lines.isEmpty()) {
            throw new InvalidClaimException("Paste at least one line of name,amount,date,note.");
        }
        out.set(new PastedLines(lines));
    }
}
EOF
cat > AddPastedClaims.java <<'EOF'
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;

public class AddPastedClaims {
    // Each checked line becomes a DRAFT claim, in order, added as the claim form adds one and recorded as CLAIM_ADDED.
    public void add(@Val PastedLines pasted, Claims claims, Sheets sheets, Settings settings, Rollup rollup,
            ServerHttpConnection connection, Audit audit, Out<PasteResponse> result) {
        String user = Audit.user(connection);
        for (PastedLine line : pasted.lines()) {
            Person person = line.person();
            ClaimInput input = line.input();
            LocalDate today = sheets.today(person.sheetId());
            LocalDate date = input.date() != null ? input.date() : today;
            LocalDate dueBy = date.plusDays(settings.terms(person.sheetId(), person.gradeOn(date), date));
            Claim claim = claims.add(person.sheetId(), person.id(), input.amount(), date, input.note(), null, dueBy);
            claims.log(claim, user.trim(), today, rollup.figure(claim));
            ClaimResponse shown = ClaimResponse.from(claim);
            audit.record(Audit.line("CLAIM_ADDED", claim.sheetId(), user, "person=" + person.name(),
                    "amount=" + shown.amount(), "date=" + shown.date()));
        }
        result.set(new PasteResponse(pasted.lines().size()));
    }
}
EOF
